{
  "core": {
    "purpose": {
      "text": "회의에 사용할 요약 자료를 만들고 싶음",
      "evidence": ["요약 자료를 만들어 회의에 사용하고 싶습니다"]
    },
    "action": {
      "text": "주제별 경향을 분석하고 요약 자료를 만듦",
      "evidence": ["주제별 경향을 분석하고", "요약 자료를 만들어"]
    },
    "object": {
      "text": "이번 주 고객 의견의 반복되는 요구와 불편 주제 및 주제별 경향",
      "evidence": ["이번 주 의견에서 주제별 경향을 분석하고", "반복해서 나오는 요구와 불편 주제"]
    },
    "input": {
      "text": "매주 접수한 고객 의견",
      "evidence": ["매주 접수한 고객 의견", "이번 주 의견"]
    },
    "output": {
      "text": "주제별 경향을 뒷받침하는 의견과 함께 정리한 요약 자료",
      "evidence": ["각 경향을 뒷받침하는 의견과 함께 요약 자료"]
    },
    "workflow": {
      "text": "고객 의견을 모두 읽고 반복되는 요구와 불편 주제를 정리한 뒤, 이번 주 의견의 주제별 경향을 분석해 뒷받침하는 의견과 함께 요약 자료를 만듦",
      "evidence": ["매주 접수한 고객 의견을 모두 읽어", "반복해서 나오는 요구와 불편 주제를 정리합니다", "이번 주 의견에서 주제별 경향을 분석하고", "각 경향을 뒷받침하는 의견과 함께 요약 자료를 만들어"]
    },
    "constraints": {
      "text": "개별 고객에게 답장을 보내거나 제품 개선의 효과를 예측하는 작업은 제외",
      "evidence": ["개별 고객에게 답장을 보내거나 제품 개선의 효과를 예측하는 작업은 제외합니다"]
    }
  }
}
